from fastapi import APIRouter, FastAPI
from fastapi.exceptions import FastAPIError

def test_circular_routers():
    router_a = APIRouter()
    router_b = APIRouter()

    @router_a.get("/a")
    def route_a():
        return {"message": "A"}

    @router_b.get("/b")
    def route_b():
        return {"message": "B"}

    print("Including B into A...")
    router_a.include_router(router_b)

    print("Including A into B...")
    try:
        router_b.include_router(router_a)
        print("Successfully included A into B (circular reference!)")
    except FastAPIError as e:
        print(f"Caught expected error: {e}")
    except Exception as e:
        print(f"Caught unexpected error: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_circular_routers()
